def compute_loss(
    logits,
    targets,
    mask: Optional[jnp.ndarray] = None,
    z_loss: float = 1e-4,
):
    """
    Dense sparse-label CE from already materialized logits.

    Correct but memory-heavy because logits are [B, T, vocab].
    PMAP training should use compute_lm_loss_from_hidden(...).
    """

    logits = logits.astype(
        jnp.float32
    )

    logits = constrain_logits(
        logits
    )

    log_z = jax.scipy.special.logsumexp(
        logits,
        axis=-1,
    )

    target_logits = jnp.take_along_axis(
        logits,
        targets[..., None],
        axis=-1,
    )[..., 0]

    per_token_xent = (
        log_z
        - target_logits
    )

    z_loss_value = (
        z_loss
        * jax.lax.square(log_z)
    )

    per_token_loss = (
        per_token_xent
        + z_loss_value
    )

    per_token_loss = constrain_loss_tensor(
        per_token_loss
    )

    z_loss_value = constrain_loss_tensor(
        z_loss_value
    )

    if mask is not None:
        mask = constrain_loss_tensor(
            mask.astype(jnp.float32)
        )

        per_token_loss *= mask
        z_loss_value *= mask

        denom = jnp.maximum(
            jnp.sum(mask),
            1.0,
        )

    else:
        denom = jnp.asarray(
            per_token_loss.size,
            dtype=jnp.float32,
        )

    total_loss = (
        jnp.sum(
            per_token_loss,
            dtype=jnp.float32,
        )
        / denom
    )

    mean_z_loss = (
        jnp.sum(
            z_loss_value,
            dtype=jnp.float32,
        )
        / denom
    )

    return total_loss, {
        "loss": total_loss,
        "z_loss": mean_z_loss,
    }


