def dense_lm_loss_only_from_hidden(
    *,
    hidden_states: jnp.ndarray,
    targets: jnp.ndarray,
    lm_head_kernel: jnp.ndarray,
    mask: Optional[jnp.ndarray] = None,
    lm_head_bias: Optional[jnp.ndarray] = None,
    z_loss: float = 1e-4,
    ignore_index: int = -100,
) -> jnp.ndarray:
    """
    Dense loss-only path.

    Same scalar math as dense_lm_loss_from_hidden(...), but does not
    construct debug metric dictionaries.
    """

    if hidden_states.ndim != 3:
        raise ValueError(
            f"hidden_states must be [B, T, D], got {hidden_states.shape}"
        )

    B, T, D = hidden_states.shape

    if targets.shape != (B, T):
        raise ValueError(
            f"targets must be [B, T]={B, T}, got {targets.shape}"
        )

    w_vocab_major, vocab_size = _as_vocab_major(
        lm_head_kernel,
        hidden_size=D,
    )

    logits = jnp.einsum(
        "btd,vd->btv",
        hidden_states,
        w_vocab_major,
        precision=lax.Precision.DEFAULT,
        preferred_element_type=jnp.float32,
    )

    if lm_head_bias is not None:
        logits = logits + lm_head_bias.astype(jnp.float32)

    logits = logits.astype(jnp.float32)
    logits = constrain_logits(logits)

    valid, safe_targets = _valid_target_mask(
        targets,
        vocab_size=vocab_size,
        ignore_index=ignore_index,
        mask=mask,
    )

    log_z = jax.scipy.special.logsumexp(
        logits,
        axis=-1,
    )

    target_logits = jnp.take_along_axis(
        logits,
        safe_targets[..., None],
        axis=-1,
    )[..., 0]

    per_token_loss = (
        log_z
        - target_logits
        + z_loss * jax.lax.square(log_z)
    )

    per_token_loss = jnp.where(
        valid,
        per_token_loss,
        0.0,
    )

    per_token_loss = constrain_loss_tensor(
        per_token_loss
    )

    denom = jnp.maximum(
        jnp.sum(valid.astype(jnp.float32)),
        1.0,
    )

    return (
        jnp.sum(
            per_token_loss,
            dtype=jnp.float32,
        )
        / denom
    )


