def tokamax_linear_ce_loss_from_hidden(
    *,
    hidden_states: jnp.ndarray,
    targets: jnp.ndarray,
    lm_head_kernel: jnp.ndarray,
    mask: Optional[jnp.ndarray] = None,
    lm_head_bias: Optional[jnp.ndarray] = None,
    z_loss: float = 0.0,
    ignore_index: int = -100,
    implementation: str = "mosaic_tpu",
) -> Tuple[jnp.ndarray, Dict[str, jnp.ndarray]]:
    """Exact sparse-label CE through the Tokamax TPU linear-softmax kernel.

    This backend is intentionally narrow: Tokamax does not accept an LM-head
    bias or z-loss, so those features trigger the caller's native fallback.
    Invalid or masked labels use a safe label and contribute zero loss/gradient.
    """
    if lm_head_bias is not None:
        raise NotImplementedError(
            "Tokamax linear CE does not support lm_head_bias; use native loss."
        )

    if z_loss != 0.0:
        raise NotImplementedError(
            "Tokamax linear CE does not support z_loss; set loss.z_loss=0.0."
        )

    if hidden_states.ndim != 3:
        raise ValueError(
            "hidden_states must be [batch, sequence, hidden]. "
            f"Got shape={hidden_states.shape}"
        )

    B, T, D = hidden_states.shape
    if targets.shape != (B, T):
        raise ValueError(
            f"targets must be [B, T]={B, T}, got {targets.shape}"
        )

    w_vocab_major, vocab_size = _as_vocab_major(
        lm_head_kernel,
        hidden_size=D,
    )
    hidden_flat = hidden_states.reshape(B * T, D)
    targets_flat = targets.astype(jnp.int32).reshape(B * T)

    if mask is None:
        mask_flat = jnp.ones((B * T,), dtype=bool)
    else:
        if mask.shape != (B, T):
            raise ValueError(
                f"mask must be [B, T]={B, T}, got {mask.shape}"
            )
        mask_flat = mask.astype(bool).reshape(B * T)

    active = (
        mask_flat
        & (targets_flat != ignore_index)
        & (targets_flat >= 0)
        & (targets_flat < vocab_size)
    )
    safe_targets = jnp.where(active, targets_flat, 0)

    # Mosaic TPU linear CE requires the flattened token dimension to be a
    # multiple of the heuristic B block (1024 when no divisor is available).
    # Llama shifts 2048-token windows to 2047 targets: 8 x 2047 = 16,376,
    # so append eight inactive rows and execute the kernel on 16,384 tokens.
    token_block = 1024
    padded_token_count = (
        (hidden_flat.shape[0] + token_block - 1)
        // token_block
        * token_block
    )
    padding = padded_token_count - hidden_flat.shape[0]
    if padding:
        hidden_flat = jnp.pad(hidden_flat, ((0, padding), (0, 0)))
        safe_targets = jnp.pad(safe_targets, (0, padding))
        active = jnp.pad(active, (0, padding), constant_values=False)


    # Tokamax expects projection weights in [hidden, vocab] layout.
    weights_hidden_major = jnp.swapaxes(w_vocab_major, 0, 1)
    # Tokamax accesses absl flags during TPU kernel setup. Parse a synthetic
    # argv so LaughLM's argparse-only flags (for example --config) are ignored.
    from absl import flags as absl_flags
    if not absl_flags.FLAGS.is_parsed():
        absl_flags.FLAGS(["laughlm"], known_only=True)

    from tokamax import linear_softmax_cross_entropy_loss

    per_token_loss = linear_softmax_cross_entropy_loss(
        hidden_flat,
        safe_targets,
        weights_hidden_major,
        reduction="none",
        implementation=implementation,
    ).astype(jnp.float32)

    active_f32 = active.astype(jnp.float32)
    token_count = jnp.maximum(jnp.sum(active_f32), 1.0)
    loss = jnp.sum(per_token_loss * active_f32) / token_count
    return loss, {
        "loss": loss,
        "z_loss": jnp.asarray(0.0, dtype=jnp.float32),
    }


def compute_lm_loss_from_hidden(
    *,
    hidden_states: jnp.ndarray,
    targets: jnp.ndarray,
    lm_head_kernel: jnp.ndarray,
    mask: Optional[jnp.ndarray] = None,
    lm_head_bias: Optional[jnp.ndarray] = None,
    chunked_logits: bool = False,
    logits_chunk_size: int = 4096,
    z_loss: float = 1e-4,
    ignore_index: int = -100,
    remat_logits_chunks: bool = True,
    kernel_backend: str = "native",
    loss_backend: str = "native",
    tokamax_implementation: str = "mosaic_tpu",
) -> Tuple[jnp.ndarray, Dict[str, jnp.ndarray]]:
    """
    Main LM loss entrypoint for full-metrics training/debug paths.
    """

    if loss_backend == "tokamax_linear_ce":
        try:
            return tokamax_linear_ce_loss_from_hidden(
                hidden_states=hidden_states,
                targets=targets,
                lm_head_kernel=lm_head_kernel,
                mask=mask,
                lm_head_bias=lm_head_bias,
                z_loss=z_loss,
                ignore_index=ignore_index,
                implementation=tokamax_implementation,
            )
        except Exception as exc:
            global _TOKAMAX_LINEAR_CE_FALLBACK_WARNED
            if not _TOKAMAX_LINEAR_CE_FALLBACK_WARNED:
                warnings.warn(
                    "Tokamax linear CE was unavailable; falling back to native "
                    f"chunked CE. Reason: {exc}",
                    stacklevel=2,
                )
                _TOKAMAX_LINEAR_CE_FALLBACK_WARNED = True
            # Preserve the native loss path if the experimental TPU kernel is unavailable.
            pass

    if kernel_backend == "tokamax":
        from LaughLM.utils.fused_ops import fused_linear_softmax_cross_entropy
        loss, z_loss_val = fused_linear_softmax_cross_entropy(
            hidden_states=hidden_states,
            targets=targets,
            weight=lm_head_kernel,
            bias=lm_head_bias,
            z_loss=z_loss,
            ignore_index=ignore_index,
            kernel_backend="tokamax",
        )
        metrics = {
            "loss": loss,
            "z_loss": z_loss_val,
        }
        return loss, metrics

    if chunked_logits:
        return chunked_lm_loss_from_hidden(
            hidden_states=hidden_states,
            targets=targets,
            lm_head_kernel=lm_head_kernel,
            mask=mask,
            lm_head_bias=lm_head_bias,
            chunk_size=logits_chunk_size,
            z_loss=z_loss,
            ignore_index=ignore_index,
            remat_chunks=remat_logits_chunks,
        )

    return dense_lm_loss_from_hidden(
        hidden_states=hidden_states,
        targets=targets,
        lm_head_kernel=lm_head_kernel,
        mask=mask,
        lm_head_bias=lm_head_bias,
        z_loss=z_loss,
        ignore_index=ignore_index,
    )
